+import { sendEmail } from '../utils/mailer';
+
+export async function processAbandonedCheckout(cartId: string, email: string) {
+  const recoveryToken = generateToken(cartId);
+  const recoveryUrl = `https://appianka.com/checkout/recover?token=${recoveryToken}`;
+  return await sendEmail({
+    to: email,
+    subject: "Completa tu compra en IANKA",
+    html: `<p>Recupera tu pedido aquí: <a href="${recoveryUrl}">Continuar Checkout</a></p>`
+  });
+}
